public class CorrectCounter {
    public static void main(String[] args) {
        int cells = 0;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                cells++;
            }
        }
        System.out.println("cells = " + cells);
    }
}

